      try {
        chatField.style.position = 'fixed'; chatField.style.right = '12px'; chatField.style.bottom = '12px'; chatField.style.left = 'auto'; chatField.style.top = 'auto';
        chatField.style.zIndex = '2147483646'; chatField.style.maxWidth = 'min(78vw,360px)'; chatField.style.background = 'rgba(12,8,20,.68)'; chatField.style.color = '#fff'; chatField.style.border = '1px solid rgba(216,180,254,.65)'; chatField.style.borderRadius = '10px'; chatField.style.backdropFilter = 'blur(8px)'; chatField.style.opacity = '.82';
        chatField.focus(); chatIsOpen = true; $('.chat-float').textContent = 'FECHAR'; $('.chat-float').setAttribute('aria-label','Minimizar chat do HaxBall'); return;
      } catch (_) {}
