  // The controls only become draggable when Editar posição is enabled; normal touches control movement/kick.
  joystick.addEventListener('pointerdown', (event) => { if (settings.editPositions) return; event.preventDefault(); pointerId = event.pointerId; try { joystick.setPointerCapture(pointerId); } catch (_) {} moveStick(event.clientX, event.clientY); });
  joystick.addEventListener('pointermove', (event) => { if (!settings.editPositions && pointerId === event.pointerId) { event.preventDefault(); moveStick(event.clientX, event.clientY); } });
