  function endKick() { sendKey(settings.kickKey, false); kickButton.classList.remove('active'); }
  kickButton.addEventListener('pointerdown', startKick);
  kickButton.addEventListener('pointerup', endKick);
  kickButton.addEventListener('pointercancel', endKick);
  kickButton.addEventListener('click', (event) => { if (settings.editPositions) { event.preventDefault(); event.stopPropagation(); } });
  kickButton.addEventListener('lostpointercapture', endKick);
  kickButton.addEventListener('contextmenu', (event) => event.preventDefault());
  window.addEventListener('blur', releaseAll);
  document.addEventListener('visibilitychange', () => { if (document.hidden) releaseAll(); });

  // Browser animation-frame estimate (not the internal game simulation FPS).
  let raf = 0, frameCount = 0, fpsStart = performance.now();
  function countFrame(now) {
    frameCount++;
    if (now - fpsStart >= 1000) {
      fpsBadge.textContent = `${Math.round(frameCount * 1000 / (now - fpsStart))} FPS · navegador`;
      frameCount = 0; fpsStart = now;
    }
    raf = requestAnimationFrame(countFrame);
  }
  raf = requestAnimationFrame(countFrame);

  // Requested 10-second animated splash, with a user-facing skip control.
